<script lang="ts">
  /**
   * The aggregator surface. Three quantities are kept visually and verbally
   * distinct and are never blended:
   *
   *  1. Pesquisas publicadas — raw house values.
   *  2. Consenso ajustado — today's nowcast.
   *  3. Projeção — the forecast for election day.
   *
   * While the live coverage gate is unsatisfied, 2 and 3 do not exist. This
   * component renders that absence as a designed state with the exact missing
   * count, and never substitutes a historical replay for 2026.
   */
  import { candidateMedia } from '../lib/candidateMedia';
  import { referenceDate } from '../lib/chartState';
  import { formatDate, formatPublishedNumber } from '../lib/format';
  import type { CurrentSignalPayload, LivePoll, OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;
  export let signal: CurrentSignalPayload | null = null;

  type Layer = 'published' | 'consensus' | 'forecast';

  const colors = ['#1f65d6', '#5b6b82', '#7c5cc4', '#14806b', '#c1652c', '#2f7eaa'];

  $: coverage = operations.live_coverage;
  $: gateSatisfied = Boolean(coverage?.gate_satisfied);
  $: missingPolls = Math.max(0, (coverage?.min_polls ?? 0) - (coverage?.polls ?? 0));
  $: missingHouses = Math.max(0, (coverage?.min_houses ?? 0) - (coverage?.houses ?? 0));
  $: livePolls = (operations.live_polls ?? []) as LivePoll[];
  $: latest = [...livePolls].sort((a, b) => referenceDate(b).localeCompare(referenceDate(a)))[0];
  $: roster = (latest?.values ?? []).slice(0, 6).map((value, index) => ({
    id: value.candidate_id,
    label: candidateMedia(value.candidate_id, value.label).displayName,
    color: colors[index % colors.length],
    latestPct: value.pct,
    house: latest?.institute ?? '',
    date: latest ? referenceDate(latest) : '',
  }));
  $: signalFor = (id: string) => signal?.signals.find((row) => row.candidate_id === id) ?? null;

  const layerCopy: Record<Layer, { title: string; blurb: string }> = {
    published: {
      title: 'Pesquisas publicadas',
      blurb: 'O que cada casa divulgou, sem nenhum ajuste. Disponível sempre.',
    },
    consensus: {
      title: 'Consenso ajustado',
      blurb:
        'Média que pondera recência, amostra, modo, dispersão entre casas e a confiabilidade histórica encolhida de cada casa.',
    },
    forecast: {
      title: 'Projeção para a eleição',
      blurb:
        'Estimativa para o dia da eleição, com o erro comum histórico e a possibilidade de mudança até lá. Não é intenção de voto de hoje.',
    },
  };
</script>

<section class="consensus-card" aria-labelledby="consensus-title">
  <header class="section-title-row">
    <div>
      <p class="mini-label">Agregador 2026 · primeiro turno</p>
      <h2 id="consensus-title">
        {gateSatisfied ? 'Consenso ajustado de hoje' : 'Agregador aguardando cobertura mínima'}
      </h2>
      <p>
        {#if gateSatisfied}
          Estimativa combinada das pesquisas registradas, ajustada pelo histórico de erro.
        {:else}
          O consenso, as probabilidades e a projeção só aparecem quando houver cobertura
          independente suficiente. Nada é estimado abaixo desse limiar.
        {/if}
      </p>
    </div>
  </header>

  {#if !gateSatisfied}
    <div class="gate-panel" role="status" aria-live="polite">
      <p class="gate-headline">
        {#if missingPolls === 1}
          Falta <strong>1 pesquisa nacional validada</strong> para o agregador publicar.
        {:else if missingPolls > 1}
          Faltam <strong>{missingPolls} pesquisas nacionais validadas</strong> para o agregador publicar.
        {:else if missingHouses > 0}
          Falta cobertura de <strong>{missingHouses} casa(s)</strong> independente(s).
        {:else}
          Cobertura mínima ainda não confirmada.
        {/if}
      </p>
      <dl class="gate-meter">
        <div>
          <dt>Pesquisas na janela</dt>
          <dd>
            <span class="gate-figure"><strong>{coverage?.polls ?? 0}</strong> de {coverage?.min_polls ?? 0}</span>
            <span class="gate-bar" role="img" aria-label={`${coverage?.polls ?? 0} de ${coverage?.min_polls ?? 0} pesquisas`}>
              <span style={`width:${Math.min(100, ((coverage?.polls ?? 0) / Math.max(1, coverage?.min_polls ?? 1)) * 100)}%`}></span>
            </span>
          </dd>
        </div>
        <div>
          <dt>Casas independentes</dt>
          <dd>
            <span class="gate-figure"><strong>{coverage?.houses ?? 0}</strong> de {coverage?.min_houses ?? 0}</span>
            <span class="gate-bar" role="img" aria-label={`${coverage?.houses ?? 0} de ${coverage?.min_houses ?? 0} casas`}>
              <span style={`width:${Math.min(100, ((coverage?.houses ?? 0) / Math.max(1, coverage?.min_houses ?? 1)) * 100)}%`}></span>
            </span>
          </dd>
        </div>
        <div>
          <dt>Janela</dt>
          <dd>
            <span class="gate-figure"><strong>{coverage?.window_days ?? 0}</strong> dias</span>
            <span class="gate-hint">Casas na janela: {(coverage?.house_ids ?? []).join(', ') || 'nenhuma'}</span>
          </dd>
        </div>
      </dl>
      <p class="gate-explainer">
        Com {coverage?.polls ?? 0} medição(ões) de {coverage?.houses ?? 0} casa(s), qualquer média
        seria dominada pela escolha de casa, não pelo eleitorado. Publicar um número aqui daria
        uma precisão que os dados não têm.
      </p>
      <p class="gate-actions">
        <a href="/pesquisas" data-route>Ver as pesquisas publicadas</a>
        <a href="/laboratorio-erro" data-route>Ver o histórico de erro das casas</a>
        <a href="/metodologia#gate" data-route>Por que este limiar existe</a>
      </p>
    </div>

    <div class="layer-legend" aria-label="As três quantidades do agregador">
      {#each Object.entries(layerCopy) as [key, copy]}
        <article class:unavailable={key !== 'published'}>
          <h3>{copy.title}</h3>
          <p>{copy.blurb}</p>
          <span class="layer-state">{key === 'published' ? 'Disponível agora' : 'Indisponível até o gate'}</span>
        </article>
      {/each}
    </div>

    {#if roster.length}
      <div class="candidate-grid" aria-label="Candidaturas na medição mais recente">
        {#each roster as candidate}
          {@const row = signalFor(candidate.id)}
          <article class="candidate-card">
            <header><span class="dot" style={`--series-color:${candidate.color}`} aria-hidden="true"></span>{candidate.label}</header>
            <dl>
              <div>
                <dt>Pesquisa mais recente</dt>
                <dd>
                  <span class="figure">{formatPublishedNumber(candidate.latestPct)}%</span>
                  <small>{candidate.house} · {candidate.date ? formatDate(candidate.date) : '—'}</small>
                </dd>
              </div>
              <div>
                <dt>Consenso ajustado</dt>
                <dd>
                  <span class="blocked">Indisponível</span>
                  <small>Bloqueado pelo gate de {coverage?.min_polls ?? 0} pesquisas / {coverage?.min_houses ?? 0} casas</small>
                </dd>
              </div>
              <div>
                <dt>Projeção para a eleição</dt>
                <dd>
                  <span class="blocked">Indisponível</span>
                  <small>Depende do consenso; nenhum forecast é calculado antes dele</small>
                </dd>
              </div>
              <div>
                <dt>Sinal atual</dt>
                <dd>
                  <span class="signal-{row?.evidence_strength ?? 'insuficiente'}">{row?.evidence_strength ?? 'insuficiente'}</span>
                  <small>{row?.explanation ?? 'Sem série comparável dentro de uma mesma casa.'}</small>
                </dd>
              </div>
            </dl>
            <a href={`/sinal-atual#${candidate.id}`} data-route>Ver como isto foi calculado</a>
          </article>
        {/each}
      </div>
    {/if}
  {:else}
    <!-- The gate passing does not by itself create a consensus: the live
         aggregate contract has to exist too. Rendering an empty card here
         would read as "no data", which is a different and false claim. -->
    <div class="gate-panel" role="status" aria-live="polite">
      <p class="gate-headline">
        Cobertura mínima atingida: <strong>{coverage?.polls ?? 0} pesquisas</strong> de
        <strong>{coverage?.houses ?? 0} casas</strong>.
      </p>
      <p class="gate-explainer">
        O contrato do consenso ajustado ainda não foi publicado para este run. Enquanto
        ele não existir, nenhum número de consenso, probabilidade ou projeção é exibido —
        o gate de cobertura é condição necessária, não suficiente.
      </p>
      <p class="gate-actions">
        <a href="/pesquisas" data-route>Ver as pesquisas publicadas</a>
        <a href="/metodologia-historica" data-route>Como o consenso é calculado</a>
      </p>
    </div>
  {/if}
</section>
