import type { Metric } from './types';

const decimal = new Intl.NumberFormat('pt-BR', {
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
});

const integer = new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 0 });

export function formatNumber(value: number): string {
  return decimal.format(value);
}

export function formatPublishedNumber(value: number): string {
  return Number.isInteger(value) ? integer.format(value) : decimal.format(value);
}

export function formatMetric(metric: Metric): string {
  if (metric.unit === 'count') return integer.format(metric.q50);
  if (metric.unit === 'probability') return `${decimal.format(metric.q50)}%`;
  if (metric.unit === 'pp') return `${metric.q50 > 0 ? '+' : ''}${decimal.format(metric.q50)} p.p.`;
  return `${decimal.format(metric.q50)}%`;
}

export function formatRange(metric: Metric): string {
  if (metric.q10 === undefined || metric.q90 === undefined) return 'faixa não disponível';
  const suffix = metric.unit === 'pp' ? ' p.p.' : '%';
  const signed = (value: number) => `${metric.unit === 'pp' && value > 0 ? '+' : ''}${decimal.format(value)}`;
  return `${signed(metric.q10)} a ${signed(metric.q90)}${suffix}`;
}

export function formatDate(value: string): string {
  const date = new Date(`${value.slice(0, 10)}T12:00:00`);
  return new Intl.DateTimeFormat('pt-BR').format(date);
}

const TIME_ZONE = 'America/Sao_Paulo';

export function formatDateTime(value: string): string {
  const date = new Date(value);
  return new Intl.DateTimeFormat('pt-BR', {
    dateStyle: 'short',
    timeStyle: 'short',
    timeZone: TIME_ZONE,
  }).format(date);
}

/** "29 de agosto de 2026, 11:21" — always in Brasília time, whatever the browser. */
export function formatDateTimeLong(value: string): string {
  const date = new Date(value);
  const day = new Intl.DateTimeFormat('pt-BR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: TIME_ZONE }).format(date);
  const time = new Intl.DateTimeFormat('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: TIME_ZONE }).format(date);
  return `${day}, ${time}`;
}

/** Signed number with the Brazilian decimal comma and a real minus sign. */
export function formatSigned(value: number, digits = 1): string {
  const formatter = new Intl.NumberFormat('pt-BR', { minimumFractionDigits: digits, maximumFractionDigits: digits });
  const magnitude = formatter.format(Math.abs(value));
  if (Math.abs(value) < 0.05) return magnitude;
  return `${value > 0 ? '+' : '−'}${magnitude}`;
}

export function formatCompactHash(value: string): string {
  return `${value.slice(0, 8)}…${value.slice(-6)}`;
}
