<script lang="ts">
  /** Progressive disclosure: objective first, formulas last. */
  import DataTable from '../components/DataTable.svelte';
  import { formatNumber } from '../lib/format';
  import type { HistoryBundle } from '../lib/types';

  export let history: HistoryBundle;

  const verdictLabel: Record<string, string> = {
    supported: 'Sustentado',
    observational: 'Observação',
    rejected: 'Rejeitado',
    unidentifiable: 'Não identificável',
  };

  $: promotion = history.integration.promotion;
  $: aggregate = promotion.aggregate;
  $: models = ['B0', 'B1', 'M2', 'MH'];
  $: patterns = history.patterns.results;
  $: grouped = {
    supported: patterns.filter((p) => p.verdict === 'supported'),
    observational: patterns.filter((p) => p.verdict === 'observational'),
    rejected: patterns.filter((p) => p.verdict === 'rejected'),
    unidentifiable: patterns.filter((p) => p.verdict === 'unidentifiable'),
  };
  const modelBlurb: Record<string, string> = {
    B0: 'Linha de base transparente: média simples da última pesquisa de cada casa.',
    B1: 'Média ponderada por recência, amostra e teto por casa.',
    M2: 'B1 mais efeitos relativos de casa estimados dentro da janela.',
    MH: 'M2 mais o histórico de erro: confiabilidade encolhida e faixa calibrada.',
  };
</script>

<section class="page-stack" aria-labelledby="hm-title">
  <header class="page-hero compact-hero">
    <p class="eyebrow">Metodologia</p>
    <h1 id="hm-title">Objetivo, o que entra e o que o histórico pode corrigir</h1>
    <p>
      Combinar pesquisas registradas no TSE com o histórico de erro das casas para estimar a
      disputa hoje e no dia da eleição, com incerteza honesta — e recusar a estimativa quando
      os dados não a sustentam.
    </p>
  </header>

  <section class="content-section" aria-labelledby="scope-title">
    <div class="section-heading"><div><p class="eyebrow">Escopo</p><h2 id="scope-title">O que entra e o que não entra</h2></div></div>
    <div class="scope-grid">
      <article>
        <h3>Entra</h3>
        <ul>
          <li>Pesquisas nacionais presidenciais com registro TSE verificado.</li>
          <li>Percentuais com evidência preservada e hash SHA-256.</li>
          <li>Resultados oficiais por turno, convertidos para votos válidos.</li>
          <li>Histórico de erro de 2010, 2014, 2018 e 2022, separado por turno.</li>
        </ul>
      </article>
      <article>
        <h3>Não entra</h3>
        <ul>
          <li>Pesquisas sem registro, sem percentual verificável ou sem evidência local.</li>
          <li>Percentuais inferidos, imputados ou lidos de capturas de tela.</li>
          <li>Exclusão discricionária de qualquer casa: só regras versionadas.</li>
          <li>Correção de viés por casa sem persistência fora da amostra.</li>
        </ul>
      </article>
    </div>
  </section>

  <section class="content-section" aria-labelledby="how-title">
    <div class="section-heading">
      <div><p class="eyebrow">Como medimos erro</p><h2 id="how-title">Cinco números diferentes, nunca somados</h2></div>
    </div>
    <dl class="metric-glossary">
      {#each history.lab.metric_definitions as definition}
        <div>
          <dt>{definition.label}</dt>
          <dd><p>{definition.plain}</p><code>{definition.formula}</code></dd>
        </div>
      {/each}
    </dl>
  </section>

  <section class="content-section" aria-labelledby="channels-title">
    <div class="section-heading">
      <div><p class="eyebrow">Histórico dentro do modelo</p><h2 id="channels-title">O que o histórico pode e não pode corrigir</h2></div>
      <p id="historico-no-modelo">Cada canal é julgado pelo seu próprio critério.</p>
    </div>
    <div class="channel-grid">
      {#each Object.entries(promotion.channels) as [key, channel]}
        <article class:adopted={channel.adopted}>
          <header>
            <h3>{channel.label}</h3>
            <span>{channel.adopted ? 'Adotado' : 'Não adotado'}</span>
          </header>
          <p>{channel.reason}</p>
          <ul class="criteria-list">
            {#each Object.entries(channel.criteria) as [name, passed]}
              <li class:pass={passed}><span aria-hidden="true">{passed ? '✓' : '✕'}</span>{name}</li>
            {/each}
          </ul>
          {#if channel.per_cycle_coverage?.length}
            <table class="mini-table">
              <caption>Cobertura 80% por ciclo retido</caption>
              <thead><tr><th>Ciclo</th><th class="num">M2</th><th class="num">MH</th></tr></thead>
              <tbody>
                {#each channel.per_cycle_coverage as row}
                  <tr>
                    <th scope="row">{row.held_out_cycle}</th>
                    <td class="num">{formatNumber(row.m2_coverage_80 * 100)}%</td>
                    <td class="num">{formatNumber(row.mh_coverage_80 * 100)}%</td>
                  </tr>
                {/each}
              </tbody>
            </table>
          {/if}
        </article>
      {/each}
    </div>
    <p class="inline-note"><strong>Gate declarado:</strong> {promotion.gate_declaration}</p>
  </section>

  <section class="content-section" aria-labelledby="validation-title">
    <div class="section-heading">
      <div><p class="eyebrow">Como validamos</p><h2 id="validation-title">Comparação fora da amostra</h2></div>
      <p>Leave-one-election-out e walk-forward, mesmo motor da produção.</p>
    </div>
    <DataTable label="Desempenho fora da amostra por modelo">
      <table>
        <thead><tr><th>Modelo</th><th>O que é</th><th class="num">Folds</th><th class="num">MAE</th><th class="num">Erro de margem</th><th class="num">Cobertura 80%</th></tr></thead>
        <tbody>
          {#each models as model}
            {@const row = aggregate[model]}
            <tr class:champion={promotion.champion === model}>
              <th scope="row">{model}</th>
              <td>{modelBlurb[model]}</td>
              <td class="num">{row?.folds ?? '—'}</td>
              <td class="num">{row?.mae === null || row?.mae === undefined ? '—' : formatNumber(row.mae)}</td>
              <td class="num">{row?.absolute_margin_error === null || row?.absolute_margin_error === undefined ? '—' : formatNumber(row.absolute_margin_error)}</td>
              <td class="num">{row?.coverage_80 === null || row?.coverage_80 === undefined ? '—' : `${formatNumber(row.coverage_80 * 100)}%`}</td>
            </tr>
          {/each}
        </tbody>
      </table>
    </DataTable>
    <p class="inline-note">
      <strong>Por que nenhum modelo foi promovido:</strong> {promotion.reason}
    </p>
  </section>

  <section class="content-section" aria-labelledby="learned-title">
    <div class="section-heading">
      <div><p class="eyebrow">O que aprendemos</p><h2 id="learned-title">Padrões sustentados, observações e hipóteses rejeitadas</h2></div>
      <p>“Observação” não é apoio implícito.</p>
    </div>
    {#each Object.entries(grouped) as [verdict, items]}
      {#if items.length}
        <h3 class="verdict-heading">{verdictLabel[verdict]} ({items.length})</h3>
        <div class="pattern-grid">
          {#each items as pattern}
            <article class:rejected={pattern.verdict === 'rejected'}>
              <header><strong>{pattern.id}</strong><span>{verdictLabel[pattern.verdict]}</span></header>
              <h4>{pattern.question}</h4>
              <p>{pattern.reading}</p>
              <details>
                <summary>Regra usada</summary>
                <p>{pattern.rule}</p>
                {#if pattern.test_power_note}<p class="inline-note">{pattern.test_power_note}</p>{/if}
                {#if pattern.algebraic_identity}<p class="inline-note">{pattern.algebraic_identity}</p>{/if}
              </details>
            </article>
          {/each}
        </div>
      {/if}
    {/each}
    <dl class="verdict-key">
      {#each Object.entries(history.patterns.verdict_meanings) as [key, meaning]}
        <div><dt>{verdictLabel[key]}</dt><dd>{meaning}</dd></div>
      {/each}
    </dl>
  </section>

  <section class="content-section" aria-labelledby="limits-title">
    <div class="section-heading"><div><p class="eyebrow">Limitações</p><h2 id="limits-title">O que este sistema não sabe</h2></div></div>
    <ul class="limitation-list">
      {#each history.integration.limitations as limitation}<li>{limitation}</li>{/each}
      {#each history.lab.coverage.known_gaps as gap}<li>{gap.gap}: {gap.detail}</li>{/each}
    </ul>
  </section>

  <section class="content-section" aria-labelledby="repro-title">
    <div class="section-heading"><div><p class="eyebrow">Reprodutibilidade</p><h2 id="repro-title">Run e hashes</h2></div></div>
    <dl class="run-facts">
      <div><dt>Run histórico</dt><dd><code>{history.lab.run_id}</code></dd></div>
      <div><dt>Data de referência</dt><dd>{history.lab.as_of}</dd></div>
      <div><dt>Hash dos dados</dt><dd><code>{history.lab.data_hash.slice(0, 16)}…</code></dd></div>
      <div><dt>Hash da configuração</dt><dd><code>{history.lab.config_hash.slice(0, 16)}…</code></dd></div>
      <div><dt>Registro de casas</dt><dd>{history.lab.house_registry_version}</dd></div>
      <div><dt>Motor</dt><dd>{history.integration.engine_version}</dd></div>
    </dl>
    <p class="chart-scope-note">
      Downloads: <a href="/data/latest/history_lab.json" download>history_lab.json</a> ·
      <a href="/data/latest/history_patterns.json" download>history_patterns.json</a> ·
      <a href="/data/latest/history_integration.json" download>history_integration.json</a> ·
      <a href="/data/latest/current_signal.json" download>current_signal.json</a> ·
      <a href="/data/latest/automatic_insights.json" download>automatic_insights.json</a>
    </p>
  </section>
</section>
