<script lang="ts">
  /**
   * "E se corrigirmos pelo erro histórico das casas?"
   *
   * Everything on this page is an exploratory scenario. The published number
   * is always shown next to the corrected one, the out-of-sample verdict that
   * refuses to validate the correction is printed in full, and nothing here
   * is called consensus, forecast or probability.
   */
  import DataTable from '../components/DataTable.svelte';
  import { candidateMedia } from '../lib/candidateMedia';
  import { formatDate, formatNumber, formatSigned } from '../lib/format';
  import type { HistoryBundle } from '../lib/types';

  export let history: HistoryBundle;

  const blocLabel: Record<string, string> = {
    esquerda: 'esquerda',
    centro: 'centro',
    direita: 'direita',
    unclassified: 'fora do eixo',
  };

  $: scenario = history.correction.scenario;
  $: ideology = history.correction.ideology;
  $: aggregate = scenario.aggregate.candidates;
  $: shown = aggregate.slice(0, 6);
  $: hidden = aggregate.slice(6);
  $: primary = ideology.persistence[ideology.primary_test];
  $: persistenceRows = Object.entries(ideology.persistence).sort(([a], [b]) => a.localeCompare(b));
  $: parties = Object.values(ideology.classification.parties).sort((a, b) => (a.party ?? '').localeCompare(b.party ?? ''));

  function displayName(id: string, label: string): string {
    return candidateMedia(id, label).displayName;
  }

  function arrow(direction: string): string {
    if (direction === 'para cima' || direction === 'a mais' || direction === 'alta') return '▲';
    if (direction === 'para baixo' || direction === 'a menos' || direction === 'baixa') return '▼';
    return '＝';
  }

  function arrowClass(direction: string): string {
    if (direction === 'para cima' || direction === 'a mais' || direction === 'alta') return 'dir dir-up';
    if (direction === 'para baixo' || direction === 'a menos' || direction === 'baixa') return 'dir dir-down';
    return 'dir dir-flat';
  }
</script>

<section class="page-stack scenario-page" aria-labelledby="scenario-title">
  <header class="page-hero compact-hero">
    <p class="eyebrow">Cenário exploratório · não é o consenso</p>
    <h1 id="scenario-title">E se corrigirmos pelo erro histórico das casas?</h1>
    <p>
      Cada pesquisa viva é corrigida pelo quanto a casa que a publicou errou, para cima ou para
      baixo, em cada lado do espectro nas eleições anteriores. O número publicado fica sempre ao
      lado. É um exercício: o teste fora da amostra diz que esse passado não prevê o erro futuro.
    </p>
  </header>

  <div class="scenario-banner" role="note">
    <span class="scenario-badge">Cenário exploratório</span>
    <p>{scenario.disclaimer}</p>
    <p class="scenario-oos"><strong>O que o teste fora da amostra diz:</strong> {scenario.out_of_sample.plain}</p>
    {#if scenario.gate.below_live_gate}
      <p class="scenario-gate">
        Abaixo do gate do agregador ({scenario.gate.polls}/{scenario.gate.min_polls} pesquisas,
        {scenario.gate.houses}/{scenario.gate.min_houses} casas em {scenario.gate.window_days} dias). {scenario.gate.note}
      </p>
    {/if}
  </div>

  <section class="content-section" aria-labelledby="aggregate-title">
    <div class="section-heading">
      <div>
        <p class="eyebrow">Agregado do cenário · votos válidos</p>
        <h2 id="aggregate-title">Publicado × corrigido, média simples das casas vivas</h2>
      </div>
      <p>{scenario.aggregate.method}. {scenario.aggregate.houses} casa(s).</p>
    </div>
    <ul class="scenario-cards" aria-label="Candidaturas no cenário corrigido">
      {#each shown as row}
        <li class="scenario-card">
          <h3>{displayName(row.candidate_id, row.label)}</h3>
          <div class="scenario-pair">
            <div>
              <span class="pair-label">Publicado</span>
              <strong>{formatNumber(row.published_valid_mean_pct)}%</strong>
            </div>
            <div class="pair-arrow" aria-hidden="true">→</div>
            <div>
              <span class="pair-label">Cenário corrigido</span>
              <strong class="scenario-figure">{formatNumber(row.corrected_valid_mean_pct)}%</strong>
            </div>
          </div>
          <p class="scenario-adjust">
            <span class={arrowClass(row.direction)} aria-hidden="true">{arrow(row.direction)}</span>
            {#if row.direction === 'sem ajuste'}
              sem ajuste
            {:else}
              ajuste de {formatSigned(row.adjustment_pp)} p.p. ({row.direction})
            {/if}
            {#if row.uncertainty_pp !== null}
              · faixa aproximada ±{formatNumber(row.uncertainty_pp)} p.p.
            {/if}
          </p>
          <small>{row.houses_adjusted} de {row.houses} casa(s) com histórico próprio · bloco {blocLabel[row.bloc] ?? row.bloc}</small>
        </li>
      {/each}
    </ul>
    {#if hidden.length}
      <details class="scenario-more">
        <summary>Ver as outras {hidden.length} candidaturas</summary>
        <DataTable label="Demais candidaturas no cenário corrigido">
          <table>
            <thead><tr><th>Candidatura</th><th class="num">Publicado</th><th class="num">Corrigido</th><th class="num">Ajuste</th><th>Bloco</th></tr></thead>
            <tbody>
              {#each hidden as row}
                <tr>
                  <th scope="row">{displayName(row.candidate_id, row.label)}</th>
                  <td class="num">{formatNumber(row.published_valid_mean_pct)}%</td>
                  <td class="num">{formatNumber(row.corrected_valid_mean_pct)}%</td>
                  <td class="num"><span class={arrowClass(row.direction)} aria-hidden="true">{arrow(row.direction)}</span> {formatSigned(row.adjustment_pp)}</td>
                  <td>{blocLabel[row.bloc] ?? row.bloc}</td>
                </tr>
              {/each}
            </tbody>
          </table>
        </DataTable>
      </details>
    {/if}
    <p class="inline-note">
      Valores em votos válidos: percentual publicado dividido pela soma das candidaturas
      publicadas. A faixa aproximada combina a dispersão do erro histórico da casa com o erro
      amostral da pesquisa; é uma ordem de grandeza, não um intervalo validado.
    </p>
  </section>

  <section class="content-section" aria-labelledby="houses-title">
    <div class="section-heading">
      <div>
        <p class="eyebrow">Por casa</p>
        <h2 id="houses-title">A pesquisa de cada casa, corrigida pelo erro dessa casa</h2>
      </div>
    </div>
    <div class="scenario-houses">
      {#each scenario.houses as house}
        <article class="scenario-house" class:no-history={house.history_status !== 'available'}>
          <header>
            <div>
              <p class="mini-label">{house.house_name} · {house.poll.registration_no}</p>
              <h3>Publicada em {formatDate(house.poll.published_at)} · campo até {formatDate(house.poll.field_end)}</h3>
            </div>
            <span class="scenario-status">{house.history_status === 'available' ? 'com histórico próprio' : 'sem histórico próprio'}</span>
          </header>
          <p class="scenario-history">{house.history_plain}</p>
          {#if house.history_reason}
            <p class="inline-note warn">Nenhum ajuste aplicado: {house.history_reason}.</p>
          {/if}
          <ol class="scenario-candidates">
            {#each house.corrected.candidates.slice(0, 6) as row}
              <li>
                <span class="scenario-name">{displayName(row.candidate_id, row.label)}</span>
                <span class="scenario-values">
                  <span>{formatNumber(row.published_valid_pct)}%</span>
                  <span class={arrowClass(row.direction)} aria-hidden="true">{arrow(row.direction)}</span>
                  <strong>{formatNumber(row.corrected_valid_pct)}%</strong>
                  <small>{row.direction === 'sem ajuste' ? 'sem ajuste' : `${formatSigned(row.adjustment_pp)} p.p.`}</small>
                </span>
                <details>
                  <summary>Por quê</summary>
                  <p>{row.sentence}</p>
                  {#if row.same_person_history}
                    <p class="scenario-same-person">{row.same_person_history.sentence}</p>
                  {/if}
                  {#if row.uncertainty_pp !== null}
                    <p class="small muted">Faixa aproximada ±{formatNumber(row.uncertainty_pp)} p.p. ({row.uncertainty_components.historical_sd_source ?? 'só erro amostral'}).</p>
                  {/if}
                </details>
              </li>
            {/each}
          </ol>
          <p class="small muted">
            Base publicada: {house.poll.base}; soma corrigida {formatNumber(house.corrected.corrected_sum_valid_pct)}%.
            {house.corrected.sum_note}
          </p>
        </article>
      {/each}
    </div>
  </section>

  <section class="content-section" aria-labelledby="ideology-title" id="eixo-ideologico">
    <div class="section-heading">
      <div>
        <p class="eyebrow">Dimensão nova · testada fora da amostra</p>
        <h2 id="ideology-title">A casa superestima um lado do espectro?</h2>
      </div>
      <p>Esquerda, centro e direita pelo partido de registro em cada eleição.</p>
    </div>
    <div class="verdict-box" class:rejected={!ideology.any_correction_authorized}>
      <strong>Resultado do teste:</strong> {ideology.verdict_plain}
    </div>
    <DataTable label="Teste fora da amostra do eixo ideológico, por variante">
      <table>
        <thead><tr><th>Variante</th><th>Janela</th><th class="num">Erro prevendo pelo passado</th><th class="num">Erro prevendo zero</th><th class="num">Sinal repete</th><th>Veredito</th></tr></thead>
        <tbody>
          {#each persistenceRows as [key, row]}
            <tr class:primary-row={key === ideology.primary_test}>
              <th scope="row">{row.axis_label}{row.relative_to_election ? ' · descontado o erro comum' : ' · bruto'}</th>
              <td>{history.lab.window_labels[row.window] ?? row.window}</td>
              <td class="num">{row.model_mae_pp === undefined || row.model_mae_pp === null ? '—' : `${formatNumber(row.model_mae_pp)} p.p.`}</td>
              <td class="num">{row.null_mae_pp === undefined || row.null_mae_pp === null ? '—' : `${formatNumber(row.null_mae_pp)} p.p.`}</td>
              <td class="num">{row.sign_agreement_rate === undefined || row.sign_agreement_rate === null ? '—' : `${formatNumber(row.sign_agreement_rate * 100)}%`}</td>
              <td>{row.status === 'tested' ? (row.correction_authorized ? 'autoriza correção' : 'não autoriza') : 'não testável'}</td>
            </tr>
          {/each}
        </tbody>
      </table>
    </DataTable>
    <p class="inline-note">{primary?.decision_rule}</p>

    <h3 class="subsection-title">Por casa: para que lado cada uma errou, descontado o erro comum de cada eleição</h3>
    <ul class="plain-list">
      {#each ideology.house_summaries_by_window.d14 as house}
        <li>
          <span class={arrowClass(house.left_minus_rest_relative.mean === null ? 'flat' : house.left_minus_rest_relative.mean > 0 ? 'a mais' : 'a menos')} aria-hidden="true">{house.left_minus_rest_relative.mean === null ? '＝' : house.left_minus_rest_relative.mean > 0 ? '◀' : '▶'}</span>
          <span>{house.plain}{house.eligible_for_out_of_sample_test ? '' : ' Menos de 3 anos eleitorais: fora do teste.'}</span>
        </li>
      {/each}
    </ul>

    <h3 class="subsection-title">Todo o setor, eleição por eleição</h3>
    <DataTable label="Erro por bloco ideológico, média com um voto por casa">
      <table>
        <thead><tr><th>Eleição</th><th class="num">Casas</th><th class="num">Esquerda</th><th class="num">Centro</th><th class="num">Direita</th><th class="num">Esquerda − demais</th></tr></thead>
        <tbody>
          {#each ideology.sector_by_election as row}
            <tr>
              <th scope="row">{row.election.replace('-T', ' · T')}</th>
              <td class="num">{row.houses}</td>
              <td class="num">{row.bloc_esquerda_pp === null ? '—' : formatSigned(row.bloc_esquerda_pp)}</td>
              <td class="num">{row.bloc_centro_pp === null ? '—' : formatSigned(row.bloc_centro_pp)}</td>
              <td class="num">{row.bloc_direita_pp === null ? '—' : formatSigned(row.bloc_direita_pp)}</td>
              <td class="num">{row.left_minus_rest_pp === null ? '—' : formatSigned(row.left_minus_rest_pp)}</td>
            </tr>
          {/each}
        </tbody>
      </table>
    </DataTable>
    <p class="inline-note">
      Positivo = o bloco apareceu nas pesquisas com mais votos do que teve na urna. Um traço
      significa que o bloco não tinha candidatura pontuada naquele turno — não é zero.
    </p>

    <details class="classification-details">
      <summary>Como cada partido foi classificado (fonte, rótulo fino e bloco)</summary>
      <p>{ideology.classification.criterion} {ideology.classification.limitation} Estado da revisão: <code>{ideology.classification.review_status}</code>.</p>
      <ul class="source-list">
        {#each ideology.classification.sources as source}
          <li><a href={source.url} target="_blank" rel="noreferrer">{source.id}</a> · acesso em {formatDate(source.accessed_at)}{source.note ? ` · ${source.note}` : ''}</li>
        {/each}
      </ul>
      <DataTable label="Classificação por partido">
        <table>
          <thead><tr><th>Partido</th><th>Rótulo da fonte</th><th>Bloco</th><th>Fonte</th></tr></thead>
          <tbody>
            {#each parties as party}
              <tr><th scope="row">{party.party}</th><td>{party.spectrum ?? '—'}</td><td>{blocLabel[party.bucket] ?? party.bucket}</td><td>{party.source ?? '—'}</td></tr>
            {/each}
          </tbody>
        </table>
      </DataTable>
    </details>
  </section>

  <section class="content-section" aria-labelledby="method-title">
    <div class="section-heading"><div><p class="eyebrow">Regras do cenário</p><h2 id="method-title">Como o ajuste foi calculado</h2></div></div>
    <dl class="run-facts">
      <div><dt>Fórmula</dt><dd>{scenario.method.formula}</dd></div>
      <div><dt>Base do erro</dt><dd>{scenario.method.basis_note}</dd></div>
      <div><dt>Linhagem</dt><dd>Não herdada: uma casa sem histórico próprio recebe ajuste zero, mesmo que descenda de outra.</dd></div>
      <div><dt>Papel no registry</dt><dd><code>{scenario.role}</code> · promovido: não · validado fora da amostra: não</dd></div>
      <div><dt>Run</dt><dd><code>{history.correction.run_id}</code></dd></div>
    </dl>
    <p class="chart-scope-note">Contrato: <a href="/data/latest/house_correction.json" download>house_correction.json</a></p>
  </section>
</section>
